use lru_cache_ttl::{CacheConfig, EvictionReason, LRUCache, PutOptions};
use std::sync::Arc;

#[tokio::main]
async fn main() {
    // no-op main. Tests are in the #[cfg(test)] mod below.
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::time::{sleep, Duration};

    #[tokio::test]
    async fn run_tests() {
        // Basic configuration: small ttl for tests
        let cfg = CacheConfig {
            max_entries: 3,
            default_ttl_ms: 100,
            ..Default::default()
        };
        let cache: LRUCache<String> = LRUCache::new(Some(cfg));

        // Basic get/put
        cache.put("a", "hello".to_string());
        let got = cache.get("a");
        assert!(got.is_some() && &*got.unwrap() == "hello", "basic get");
        assert_eq!(cache.size(), 1, "size after put");

        // LRU eviction
        cache.put("b", "world".to_string());
        cache.put("c", "foo".to_string());
        cache.put("d", "bar".to_string()); // should evict LRU ('a')
        assert!(!cache.has("a"), "lru eviction");
        assert!(cache.has("d"), "newest kept");

        // TTL expiration
        cache.clear();
        cache.put_with_options("x", "temp".to_string(), Some(50), None);
        sleep(Duration::from_millis(80)).await;
        assert!(cache.get("x").is_none(), "ttl expired");

        // Access order
        cache.clear();
        cache.put("1", "one".to_string());
        cache.put("2", "two".to_string());
        cache.put("3", "three".to_string());
        let _ = cache.get("1"); // access '1', making '2' the LRU
        cache.put("4", "four".to_string()); // should evict '2'
        assert!(!cache.has("2"), "access order eviction");
        assert!(cache.has("1"), "accessed item kept");

        // Stats
        let stats = cache.get_stats();
        assert!(stats.hits > 0, "has hits");
        assert!(stats.misses > 0, "has misses");

        // Eviction loop
        let cfg2 = CacheConfig {
            max_entries: 10,
            default_ttl_ms: 50,
            eviction_check_interval_ms: 30,
            ..Default::default()
        };
        let cache2: LRUCache<String> = LRUCache::new(Some(cfg2));
        cache2.put("e1", "val1".to_string());
        cache2.start_eviction_loop();
        sleep(Duration::from_millis(150)).await;
        assert!(!cache2.has("e1"), "eviction loop cleared expired");
        cache2.stop_eviction_loop();

        println!("All tests passed");
    }
}
